// Generated from readable original Dialog TextAssets; numbered text replay only.
export default {"scenes":[{"id":"CityEventH102","characterId":"hero_102","lines":[{"number":1,"text":"Ah, it's really you! I followed the scent of treasure and came here. So, it seems that you really have a lot of beautiful jewels!","sourceKey":"Dialog:context:CityEventH102-1","speaker":null},{"number":2,"text":"Hey, let me have a look too, pretty please.","sourceKey":"Dialog:context:CityEventH102-2","speaker":null}]},{"id":"CityEventH11","characterId":"hero_11","lines":[{"number":1,"text":"Are you from the inn? Your meat has arrived, please check the quantity.","sourceKey":"Dialog:context:CityEventH11-1","speaker":null},{"number":2,"text":"Eh? May I ask who you are...?","sourceKey":"Dialog:context:CityEventH11-2","speaker":"{playerName}"},{"number":3,"text":"I'm a hunter, I made an agreement with Miss Belle to supply meat for the inn. She used to handle the exchange herself.","sourceKey":"Dialog:context:CityEventH11-3","speaker":null},{"number":4,"text":"You must be the new \"employer\" Miss Belle mentioned to me.","sourceKey":"Dialog:context:CityEventH11-4","speaker":null},{"number":5,"text":"This is a good chance to introduce ourselves, if you ever want a delicious cut of meat, just come find me.","sourceKey":"Dialog:context:CityEventH11-5","speaker":null}]},{"id":"CityEventH12","characterId":"hero_12","lines":[{"number":1,"text":"{playerName}, do you have a moment? I want to talk to you about something.","sourceKey":"Dialog:context:CityEventH12-1","speaker":null},{"number":2,"text":"Ok~ So Belle has actually come looking for me~","sourceKey":"Dialog:context:CityEventH12-2","speaker":"{playerName}"},{"number":3,"text":"Ah, it's not because someone found out I ate Fifi's pudding, is it...?","sourceKey":"Dialog:context:CityEventH12-3","speaker":"{playerName}"},{"number":4,"text":"It's not about that... Wait—you actually ate her pudding?!","sourceKey":"Dialog:context:CityEventH12-4","speaker":null},{"number":5,"text":"I-I'm sorry! I only realized there was a label on it after I ate it...","sourceKey":"Dialog:context:CityEventH12-5","speaker":"{playerName}"},{"number":6,"text":"We'll talk about that later... Um, if you don't mind, would you let me join your team too?","sourceKey":"Dialog:context:CityEventH12-6","speaker":null},{"number":7,"text":"Eh? You want to become my Fellow?!","sourceKey":"Dialog:context:CityEventH12-7","speaker":"{playerName}"},{"number":8,"text":"What, am I not welcome?","sourceKey":"Dialog:context:CityEventH12-8","speaker":null},{"number":9,"text":"Of course you are! I've been hoping you would join me~","sourceKey":"Dialog:context:CityEventH12-9","speaker":"{playerName}"},{"number":10,"text":"But why are you telling me now? Did you have reservations about partnering up before...?","sourceKey":"Dialog:context:CityEventH12-10","speaker":"{playerName}"},{"number":11,"text":"It has nothing to do with you. It's because I was gullible enough to believe Creos, which led to Fifi and me getting into debt.","sourceKey":"Dialog:context:CityEventH12-11","speaker":null},{"number":12,"text":"When you extended a helping hand to us, I was worried it was another trap...","sourceKey":"Dialog:context:CityEventH12-12","speaker":null},{"number":13,"text":"But after spending this much time with you, I understand that you're a kind person.","sourceKey":"Dialog:context:CityEventH12-13","speaker":null},{"number":14,"text":"I'm truly sorry for continuing to doubt you even when you were helping us.","sourceKey":"Dialog:context:CityEventH12-14","speaker":null},{"number":15,"text":"It's okay! You've helped me a lot, too. We're friends now~","sourceKey":"Dialog:context:CityEventH12-15","speaker":"{playerName}"},{"number":16,"text":"I'm glad we can be honest with each other now~","sourceKey":"Dialog:context:CityEventH12-16","speaker":"{playerName}"},{"number":17,"text":"Humph... In any case, just tell me if there's any work to be done.","sourceKey":"Dialog:context:CityEventH12-17","speaker":null},{"number":18,"text":"Please take care of me from now on... Fellow.","sourceKey":"Dialog:context:CityEventH12-18","speaker":null}]},{"id":"CityEventH13","characterId":"hero_13","lines":[{"number":1,"text":"Greetings, {playerName}. How have you been?","sourceKey":"Dialog:context:CityEventH13-1","speaker":null},{"number":2,"text":"It's Lincale! Thanks to you, the scroll shop is thriving now.","sourceKey":"Dialog:context:CityEventH13-2","speaker":"{playerName}"},{"number":3,"text":"Heheh, it's my greatest honor to be of help to you.","sourceKey":"Dialog:context:CityEventH13-3","speaker":null},{"number":4,"text":"But recently, everyone has been hoping for more types of magic scrolls, and no one here understands magic design...","sourceKey":"Dialog:context:CityEventH13-4","speaker":"{playerName}"},{"number":5,"text":"If you could lend a hand, that would be great. If you're not too busy?","sourceKey":"Dialog:context:CityEventH13-5","speaker":"{playerName}"},{"number":6,"text":"That certainly is a coincidence, that's exactly why I came to visit you.","sourceKey":"Dialog:context:CityEventH13-6","speaker":null},{"number":7,"text":"Thanks to your guidance, after spending some time studying I have fully understood the principles that give the Universal Recovery Potion its effects.","sourceKey":"Dialog:context:CityEventH13-7","speaker":null},{"number":8,"text":"There's nothing I need more right now than opportunities to practice what I've learned. Developing new magic scrolls would be an excellent place to start.","sourceKey":"Dialog:context:CityEventH13-8","speaker":null},{"number":9,"text":"If you're willing to take me on that would be wonderful. After all, we are Fellows who have worked together before.","sourceKey":"Dialog:context:CityEventH13-9","speaker":null},{"number":10,"text":"Really!? That's perfect! With the authoritative Lincale on our side, the scroll shop will do even better for sure!","sourceKey":"Dialog:context:CityEventH13-10","speaker":"{playerName}"},{"number":11,"text":"Heheh, you're too kind~ Please let me contribute to the village in whatever way I can.","sourceKey":"Dialog:context:CityEventH13-11","speaker":null}]},{"id":"CityEventH14","characterId":"hero_14","lines":[{"number":1,"text":"The harvest at the farmstead has been good lately. You can smell the fragrance of a bountiful harvest from far away~","sourceKey":"Dialog:context:CityEventH14-1","speaker":"{playerName}"},{"number":2,"text":"Baa~!","sourceKey":"Dialog:context:CityEventH14-2","speaker":"Lost Lamb"},{"number":3,"text":"Wow! Where did this little lamb come from? So cute~","sourceKey":"Dialog:context:CityEventH14-3","speaker":"{playerName}"},{"number":4,"text":"Curly? Is that Curly? Oh, I'm sorry for bothering you.","sourceKey":"Dialog:context:CityEventH14-4","speaker":null},{"number":5,"text":"I'm a shepherd. This little lamb ran away while I wasn't paying attention.","sourceKey":"Dialog:context:CityEventH14-5","speaker":null},{"number":6,"text":"Oh, it's okay... Um, why are we standing so close...?","sourceKey":"Dialog:context:CityEventH14-6","speaker":"{playerName}"},{"number":7,"text":"Sorry, my eyesight isn't good. I can't see anything if I'm not close. I rely on smell to herd the sheep.","sourceKey":"Dialog:context:CityEventH14-7","speaker":null},{"number":8,"text":"The air is filled with a very nice scent of herbs. Maybe Curly was attracted by this smell.","sourceKey":"Dialog:context:CityEventH14-8","speaker":null},{"number":9,"text":"Alright, let's go back. We can't just munch on someone else's grass...","sourceKey":"Dialog:context:CityEventH14-9","speaker":null},{"number":10,"text":"...... Baa~","sourceKey":"Dialog:context:CityEventH14-10","speaker":"Lost Lamb"},{"number":11,"text":"The little lamb doesn't seem to want to leave. You're always welcome to bring them here to graze, the grass is always fresh~","sourceKey":"Dialog:context:CityEventH14-11","speaker":"{playerName}"},{"number":12,"text":"Really? I'd hate to trouble you.","sourceKey":"Dialog:context:CityEventH14-12","speaker":null},{"number":13,"text":"It's fine. Being able to see such an adorable little lamb every day will make everyone in the village happy~","sourceKey":"Dialog:context:CityEventH14-13","speaker":"{playerName}"},{"number":14,"text":"Then I won't decline! Keep an eye out for me and Curly in the future.","sourceKey":"Dialog:context:CityEventH14-14","speaker":null}]},{"id":"CityEventH15","characterId":"hero_15","lines":[{"number":1,"text":"Haha~ Today is a perfect day for fishing! Big fish, here I come!","sourceKey":"Dialog:context:CityEventH15-1","speaker":null},{"number":2,"text":"(Wow, another cute Kemonomimi girl!) Hello! Welcome to town~","sourceKey":"Dialog:context:CityEventH15-2","speaker":"{playerName}"},{"number":3,"text":"Hi! My name is Kaity, I'm a professional fisher!","sourceKey":"Dialog:context:CityEventH15-3","speaker":null},{"number":4,"text":"A fisher? I doesn't seem like anyone has ever fished before. Can you really catch anything?","sourceKey":"Dialog:context:CityEventH15-4","speaker":"{playerName}"},{"number":5,"text":"That's what makes it challenging! I've only caught treasure and stuff here, but I won't give up!","sourceKey":"Dialog:context:CityEventH15-5","speaker":null},{"number":6,"text":"You've got a great attitude...","sourceKey":"Dialog:context:CityEventH15-6","speaker":"{playerName}"},{"number":7,"text":"... Wait, did you say treasure!?","sourceKey":"Dialog:context:CityEventH15-7","speaker":"{playerName}"},{"number":8,"text":"I heard something was buried here long ago, but I wasn't sure if it was true or not. Could you let me fish here until I make a big catch?","sourceKey":"Dialog:context:CityEventH15-8","speaker":null},{"number":9,"text":"Please do! I'd be glad to help you sort through the useless treasure too!","sourceKey":"Dialog:context:CityEventH15-9","speaker":"{playerName}"},{"number":10,"text":"Really? That would be great! You're so nice, guess I'll stay here for a while then.","sourceKey":"Dialog:context:CityEventH15-10","speaker":null}]},{"id":"CityEventH16","characterId":"hero_16","lines":[{"number":1,"text":"Hello! I'm a baker who's currently on a journey of self-discovery, I'm trying to learn about the recipes and flavors of different places.","sourceKey":"Dialog:context:CityEventH16-1","speaker":null},{"number":2,"text":"It's so lively here with so many different races living together~ Would you be willing to let me stay for a while and learn?","sourceKey":"Dialog:context:CityEventH16-2","speaker":null},{"number":3,"text":"Who wouldn't love delicious bread? Welcome, welcome!","sourceKey":"Dialog:context:CityEventH16-3","speaker":"{playerName}"},{"number":4,"text":"Ah, are these your apprentices on the tray? They're so cute~","sourceKey":"Dialog:context:CityEventH16-4","speaker":"{playerName}"},{"number":5,"text":"Hahaha! These are all made of bread, you might have to look carefully~","sourceKey":"Dialog:context:CityEventH16-5","speaker":null},{"number":6,"text":"Wow, it really is bread... They look so real...","sourceKey":"Dialog:context:CityEventH16-6","speaker":"{playerName}"},{"number":7,"text":"Thank you for the praise! When my skills improve, my work will be even better! Just you wait and see!","sourceKey":"Dialog:context:CityEventH16-7","speaker":null}]},{"id":"CityEventH17","characterId":"hero_17","lines":[{"number":1,"text":"Hey hey... The secret vintage of the Fairy Folk is ready~","sourceKey":"Dialog:context:CityEventH17-1","speaker":null},{"number":2,"text":"What a strong aroma! Are you alright? You look a little tipsy...","sourceKey":"Dialog:context:CityEventH17-2","speaker":"{playerName}"},{"number":3,"text":"Oh, a customer! Do you want a drink? I'm the most famous winemaker in the area~","sourceKey":"Dialog:context:CityEventH17-3","speaker":null},{"number":4,"text":"How about it? Can you smell the aroma of the wine~? It's a honey wine made with the Fairy Clan's secret recipe, it's very popular around here.","sourceKey":"Dialog:context:CityEventH17-4","speaker":null},{"number":5,"text":"Oh, hahaha... I-Is that so...","sourceKey":"Dialog:context:CityEventH17-5","speaker":"{playerName}"},{"number":6,"text":"Come and have a taste~ I promise that after you drink it, you'll forget all your troubles and feel as happy as if you were in heaven...","sourceKey":"Dialog:context:CityEventH17-6","speaker":null},{"number":7,"text":"Say something already, I've been doing all the talking and you haven't said a thing...","sourceKey":"Dialog:context:CityEventH17-7","speaker":null},{"number":8,"text":"Why are you talking to that tree?! I'm over here!","sourceKey":"Dialog:context:CityEventH17-8","speaker":"{playerName}"}]},{"id":"CityEventH18","characterId":"hero_18","lines":[{"number":1,"text":"Fresh, jumping life... *Kukukuku*.... Such enviable vitality.","sourceKey":"Dialog:context:CityEventH18-1","speaker":null},{"number":2,"text":"Zombie!? Ahhhh help—! It's got me—!","sourceKey":"Dialog:context:CityEventH18-2","speaker":"{playerName}"},{"number":3,"text":"The more lively the life, the more scared of death. Very good... So exciting!","sourceKey":"Dialog:context:CityEventH18-3","speaker":null},{"number":4,"text":"The zombie quickly presses down on your hurting waist with force.","sourceKey":"Dialog:context:CityEventH18-4","speaker":"empty"},{"number":5,"text":"How is that? Is the pain still strong?","sourceKey":"Dialog:context:CityEventH18-5","speaker":null},{"number":6,"text":"Ow ow... eh? It doesn't hurt anymore! What did you do?","sourceKey":"Dialog:context:CityEventH18-6","speaker":"{playerName}"},{"number":7,"text":"Fatigue has been building in your body, it was triggered by a moment of shock. You turned violently to run and were injured","sourceKey":"Dialog:context:CityEventH18-7","speaker":null},{"number":8,"text":"It wasn't serious yet, but if you continue to overwork yourself... Even more terrifying consequences may ensue...","sourceKey":"Dialog:context:CityEventH18-8","speaker":null},{"number":9,"text":"Oh my god, that sounds terrifying... I guess I have been overworking myself recently. Thanks a lot!","sourceKey":"Dialog:context:CityEventH18-9","speaker":"{playerName}"},{"number":10,"text":"Treating the symptoms is easy, but with current medical science total cures are very difficult. This could cause long-term issues.","sourceKey":"Dialog:context:CityEventH18-10","speaker":null},{"number":11,"text":"Oh man, then what should I do? I'm still young, I don't want to spend my whole life in a hospital bed!","sourceKey":"Dialog:context:CityEventH18-11","speaker":"{playerName}"},{"number":12,"text":"Utilize my \"treatment method\" and receive regular check-ups. I expect you will see results.","sourceKey":"Dialog:context:CityEventH18-12","speaker":null},{"number":13,"text":"Of course, the means of treatment will not be gentle. *Kukukuku*... Well, do you have the courage for it?","sourceKey":"Dialog:context:CityEventH18-13","speaker":null},{"number":14,"text":"I'm a little scared, but for the sake of my health I'm willing to try! Thanks again, I'm counting on you!","sourceKey":"Dialog:context:CityEventH18-14","speaker":"{playerName}"},{"number":15,"text":"Is this the courage of the living? How beautiful... Well, there's no time to waste. Let's start the first treatment right away...","sourceKey":"Dialog:context:CityEventH18-15","speaker":null}]},{"id":"CityEventH19","characterId":"hero_19","lines":[{"number":1,"text":"Ah, {playerName}! Hello!","sourceKey":"Dialog:context:CityEventH19-1","speaker":null},{"number":2,"text":"If it isn't Prim! Long time no see~","sourceKey":"Dialog:context:CityEventH19-2","speaker":"{playerName}"},{"number":3,"text":"Thanks to {playerName}'s help, the Evil Forest has been restored to its original state. Prim has come to repay the favor!","sourceKey":"Dialog:context:CityEventH19-3","speaker":null},{"number":4,"text":"That's very kind of you, Prim, but there's no need for any repayment. As long as everyone is happy, that's enough~","sourceKey":"Dialog:context:CityEventH19-4","speaker":"{playerName}"},{"number":5,"text":"I bet you think Prim is too young and inexperienced to be of any use, {playerName}. But you're wrong! ","sourceKey":"Dialog:context:CityEventH19-5","speaker":null},{"number":6,"text":"I'll have you know that Prim is a merchant already!","sourceKey":"Dialog:context:CityEventH19-6","speaker":null},{"number":7,"text":"Wow, a merchant?","sourceKey":"Dialog:context:CityEventH19-7","speaker":"{playerName}"},{"number":8,"text":"The goods in your shops require a lot of raw materials, right? Prim can go to Drakenberg to purchase any rare materials you need.","sourceKey":"Dialog:context:CityEventH19-8","speaker":null},{"number":9,"text":"I'll post the orders, and if you want anything, I'll help by going to Drakenberg to procure them.","sourceKey":"Dialog:context:CityEventH19-9","speaker":null},{"number":10,"text":"That would be a great help! I really didn't expect you to be so competent at such a young age, Prim.","sourceKey":"Dialog:context:CityEventH19-10","speaker":"{playerName}"},{"number":11,"text":"Heheh~ Didn't expect it, did you? Just let Prim do what she can!","sourceKey":"Dialog:context:CityEventH19-11","speaker":null}]},{"id":"CityEventH191","characterId":"hero_191","lines":[{"number":1,"text":"I can smell the scent of wealth on you, it's truly enviable~ To have amassed such a fortune at such a young age...","sourceKey":"Dialog:context:CityEventH191-1","speaker":null},{"number":2,"text":"Managing and making money must be simple for you. I wonder if you'd like to try a more... exciting challenge?","sourceKey":"Dialog:context:CityEventH191-2","speaker":null},{"number":3,"text":"Hehe, if you have the courage, let me open the door to a new world for you~","sourceKey":"Dialog:context:CityEventH191-3","speaker":null}]},{"id":"CityEventH20","characterId":"hero_20","lines":[{"number":1,"text":"Huh? When was this statue placed here? I don't remember this being here...","sourceKey":"Dialog:context:CityEventH20-1","speaker":"{playerName}"},{"number":2,"text":"The craftsmanship is really exquisite. It looks so real—","sourceKey":"Dialog:context:CityEventH20-2","speaker":"{playerName}"},{"number":3,"text":"Hahaha! That tickles, don't poke without asking!","sourceKey":"Dialog:context:CityEventH20-3","speaker":null},{"number":4,"text":"It spoke!? The statue came to life-!","sourceKey":"Dialog:context:CityEventH20-4","speaker":"{playerName}"},{"number":5,"text":"Sorry, sorry, I should have greeted you first~ I’m a gargoyle, I'm only active at night.","sourceKey":"Dialog:context:CityEventH20-5","speaker":null},{"number":6,"text":"I used to live in the Dungeon but there’s no difference between night and dark there. For a gargoyle, that’s unbearable!","sourceKey":"Dialog:context:CityEventH20-6","speaker":null},{"number":7,"text":"Your little town is very famous, everyone says it’s a good place to look for work. I took a look around today and found that the reputation is well-earned~","sourceKey":"Dialog:context:CityEventH20-7","speaker":null},{"number":8,"text":"Um, do you think you could let me live here? I'll take care of night watch and guard everyone!","sourceKey":"Dialog:context:CityEventH20-8","speaker":null}]},{"id":"CityEventH21","characterId":"hero_21","lines":[{"number":1,"text":"How is this hat floating in mid-air!? Have I been... have I been working too hard?","sourceKey":"Dialog:context:CityEventH21-1","speaker":"{playerName}"},{"number":2,"text":"——!","sourceKey":"Dialog:context:CityEventH21-2","speaker":null},{"number":3,"text":"Oh, what a cute little bunny~ Come here, let me pet you—","sourceKey":"Dialog:context:CityEventH21-3","speaker":"{playerName}"},{"number":4,"text":"Ta-dah~! The grand magician, igniter of miracles, has made her splendid appearance--!","sourceKey":"Dialog:context:CityEventH21-4","speaker":null},{"number":5,"text":"Whoa, the little bunny turned into a beautiful girl!","sourceKey":"Dialog:context:CityEventH21-5","speaker":"{playerName}"},{"number":6,"text":"Hehe~ That's my grand trick, what do you think? Isn't it wonderful~?","sourceKey":"Dialog:context:CityEventH21-6","speaker":null},{"number":7,"text":"It's amazing how seamless it is, just like magic...","sourceKey":"Dialog:context:CityEventH21-7","speaker":"{playerName}"},{"number":8,"text":"Of course~ My magic isn’t like the magic other people cast, it really is a “miracle” y’know!","sourceKey":"Dialog:context:CityEventH21-8","speaker":null},{"number":9,"text":"Can I do a show here? I love this little town! It feels so cozy~","sourceKey":"Dialog:context:CityEventH21-9","speaker":null},{"number":10,"text":"In return, I'll show you the newest magic in the kingdom~","sourceKey":"Dialog:context:CityEventH21-10","speaker":null}]},{"id":"CityEventH22","characterId":"hero_22","lines":[{"number":1,"text":"Hello, so we finally meet! The greatest lord I've ever known!","sourceKey":"Dialog:context:CityEventH22-1","speaker":null},{"number":2,"text":"Um, hello, nice to meet you... Do you really know me?","sourceKey":"Dialog:context:CityEventH22-2","speaker":"{playerName}"},{"number":3,"text":"Of course, I've been keeping an eye on you since you were still a little monster!","sourceKey":"Dialog:context:CityEventH22-3","speaker":null},{"number":4,"text":"It's amazing that you managed to build this village into such a prosperous hamlet, and in such a short time. You are truly talented and wise!","sourceKey":"Dialog:context:CityEventH22-4","speaker":null},{"number":5,"text":"Please let me offer my strength to you!","sourceKey":"Dialog:context:CityEventH22-5","speaker":null},{"number":6,"text":"Your praise is too much, really~ But this is the first time we're meeting, right? How did you know all this?","sourceKey":"Dialog:context:CityEventH22-6","speaker":"{playerName}"},{"number":7,"text":"I saw it with my own eyes, of course! I witnessed the progression of your great feats from the forest several hundred yards away!","sourceKey":"Dialog:context:CityEventH22-7","speaker":null},{"number":8,"text":"Wow, that's a long way away...","sourceKey":"Dialog:context:CityEventH22-8","speaker":"{playerName}"},{"number":9,"text":"Haha, eagles have good eyesight. From now on, please let me be your eyes!","sourceKey":"Dialog:context:CityEventH22-9","speaker":null}]},{"id":"CityEventH23","characterId":"hero_23","lines":[{"number":1,"text":"Hello~!","sourceKey":"Dialog:context:CityEventH23-1","speaker":"???"},{"number":2,"text":"Oh, it's Rogile. Is there something you need from me?","sourceKey":"Dialog:context:CityEventH23-2","speaker":"{playerName}"},{"number":3,"text":"Actually... I’m here to give you some super-secret inside information!","sourceKey":"Dialog:context:CityEventH23-3","speaker":"Rogile"},{"number":4,"text":"What information?","sourceKey":"Dialog:context:CityEventH23-4","speaker":"{playerName}"},{"number":5,"text":"\"Shocking news! The once kind Village Elder has refused to take on... an apprentice who came all the way from Drakenberg to study with him!\"","sourceKey":"Dialog:context:CityEventH23-5","speaker":"Rogile"},{"number":6,"text":"Huh!? Wait, are they talking about me...? But no one has come asking to be my apprentice recently, where did this fake news come from...?","sourceKey":"Dialog:context:CityEventH23-6","speaker":"{playerName}"},{"number":7,"text":"How was my delivery— not bad, right?","sourceKey":"Dialog:context:CityEventH23-7","speaker":"Rogile"},{"number":8,"text":"... What the-?","sourceKey":"Dialog:context:CityEventH23-8","speaker":"{playerName}"},{"number":9,"text":"After learning the \"Art of Headlines\" from you before, our newspaper's sales have doubled!","sourceKey":"Dialog:context:CityEventH23-9","speaker":"Rogile"},{"number":10,"text":"I’d like to stay here and keep learning from you so that I can write even more eye-catching articles in the future. Hehe... you won't refuse me, will you?","sourceKey":"Dialog:context:CityEventH23-10","speaker":"Rogile"},{"number":11,"text":"I see... Staying here to learn is fine, but next time... please don't scare me with such an incriminating headline!","sourceKey":"Dialog:context:CityEventH23-11","speaker":"{playerName}"}]},{"id":"CityEventH24","characterId":"hero_24","lines":[{"number":1,"text":"Hi! Are you, {playerName}? I'm a manager, I'm responding to the job opening at the farmstead!","sourceKey":"Dialog:context:CityEventH24-1","speaker":null},{"number":2,"text":"Oh, hello, it's me, it's me.","sourceKey":"Dialog:context:CityEventH24-2","speaker":"{playerName}"},{"number":3,"text":"(The village is prospering, and the Farmstead is growing too large for one person to handle.)","sourceKey":"Dialog:context:CityEventH24-3","speaker":"{playerName}"},{"number":4,"text":"(Finally hired someone after the job posting has been up for so long. It's convenient now.)","sourceKey":"Dialog:context:CityEventH24-4","speaker":"{playerName}"},{"number":5,"text":"(But I didn't expect her to be such a cute little girl, let me see.)","sourceKey":"Dialog:context:CityEventH24-5","speaker":"{playerName}"},{"number":6,"text":"(Huh...? Why are her legs made of wood? Is this...a scarecrow?)","sourceKey":"Dialog:context:CityEventH24-6","speaker":"{playerName}"},{"number":7,"text":"Um, excuse me for asking, but can your body...really function properly?","sourceKey":"Dialog:context:CityEventH24-7","speaker":"{playerName}"},{"number":8,"text":"Haha~ Don't worry, I'm good at doing farm work! I can carry heavy things!","sourceKey":"Dialog:context:CityEventH24-8","speaker":null},{"number":9,"text":"No, I'm not worried about that aspect...","sourceKey":"Dialog:context:CityEventH24-9","speaker":"{playerName}"},{"number":10,"text":"And the birds nearby and I are all good friends! As long as I'm here, they won't eat the crops.","sourceKey":"Dialog:context:CityEventH24-10","speaker":null},{"number":11,"text":"Hmm...(Is this really how a scarecrow's job is supposed to be done?)","sourceKey":"Dialog:context:CityEventH24-11","speaker":"{playerName}"},{"number":12,"text":"(Anyway, forget it. Since she's so cute, let's just hire her.)","sourceKey":"Dialog:context:CityEventH24-12","speaker":"{playerName}"}]},{"id":"CityEventH25","characterId":"hero_25","lines":[{"number":1,"text":"Ah, {playerName}! Over here! I've been looking for you.","sourceKey":"Dialog:context:CityEventH25-1","speaker":"Drakenberg Boatman"},{"number":2,"text":"Hmm? I remember you, you're a boatman at the Drakenberg port...","sourceKey":"Dialog:context:CityEventH25-2","speaker":"{playerName}"},{"number":3,"text":"It's Boatter, Boatter! You always take my boat when you come to the city, but you can't even remember my name.","sourceKey":"Dialog:context:CityEventH25-3","speaker":null},{"number":4,"text":"Ah... sorry about that, Boatter. What brings you here today?","sourceKey":"Dialog:context:CityEventH25-4","speaker":"{playerName}"},{"number":5,"text":"Um, I want to become a disciple of yours, {playerName}! Please take me on as a student!","sourceKey":"Dialog:context:CityEventH25-5","speaker":null},{"number":6,"text":"Ah!? What made you want to do this all of a sudden? I don't even know how to row a boat...","sourceKey":"Dialog:context:CityEventH25-6","speaker":"{playerName}"},{"number":7,"text":"It has nothing to do with boats. I want {playerName} to teach me the secret of becoming an adult!","sourceKey":"Dialog:context:CityEventH25-7","speaker":null},{"number":8,"text":"An adult? You’re still a child, you'll naturally grow up in a few years...","sourceKey":"Dialog:context:CityEventH25-8","speaker":"{playerName}"},{"number":9,"text":"That's too slow! I can't wait! I want to become a mature adult like {playerName}!","sourceKey":"Dialog:context:CityEventH25-9","speaker":null},{"number":10,"text":"Every time {playerName} takes a boat trip they’re always generous and kind, even if it means going to lots of places or spending a whole day onboard...","sourceKey":"Dialog:context:CityEventH25-10","speaker":null},{"number":11,"text":"And I noticed something else! Every once in a while, someone leaves a letter for you at the dock, because they want to see {playerName} again!","sourceKey":"Dialog:context:CityEventH25-11","speaker":null},{"number":12,"text":"Ahaha... Um, there are various reasons for that...","sourceKey":"Dialog:context:CityEventH25-12","speaker":"{playerName}"},{"number":13,"text":"So free, so at ease— that must be the true charm of being an “adult!\"","sourceKey":"Dialog:context:CityEventH25-13","speaker":null},{"number":14,"text":"I want to become an adult like you! Please teach me, {playerName}... Oh no, I mean, Master!","sourceKey":"Dialog:context:CityEventH25-14","speaker":null}]},{"id":"CityEventH03","characterId":"hero_3","lines":[{"number":1,"text":"Aah... Given the boot again, alas...","sourceKey":"Dialog:context:CityEventH03-1","speaker":null},{"number":2,"text":"Were you singing bawdy songs in the inn again? You know it some of the guests don't like it.","sourceKey":"Dialog:context:CityEventH03-2","speaker":"{playerName}"},{"number":3,"text":"‘Twas a most elegant composition! After tasting forbidden fruit, the princess was confronted by evil tentacles most vile—","sourceKey":"Dialog:context:CityEventH03-3","speaker":null},{"number":4,"text":"That doesn't sound elegant at all! Can't you sing some normal songs?","sourceKey":"Dialog:context:CityEventH03-4","speaker":"{playerName}"},{"number":5,"text":"Alas, ‘tis the only type of balladry I knoweth. Nobody would proffer coin to me should I sing aught but these ribald tunes.","sourceKey":"Dialog:context:CityEventH03-5","speaker":null},{"number":6,"text":"[Reincarnated one, strive to improve your rank. More Fellows are waiting for you—]","sourceKey":"Dialog:context:CityEventH03-6","speaker":null},{"number":7,"text":"Such lyrics are totally incomprehensible, none but a fool would listen to that drivel~","sourceKey":"Dialog:context:CityEventH03-7","speaker":null},{"number":8,"text":"Wait a second—what were you just singing?","sourceKey":"Dialog:context:CityEventH03-8","speaker":"{playerName}"},{"number":9,"text":"Hmm? ‘Tis the contents of a book of prophecy, I merely sang it according to a simple rhythm. The meaning is quite beyond me, I'm afraid.","sourceKey":"Dialog:context:CityEventH03-9","speaker":null},{"number":10,"text":"(Prophecy? It must be about me! Maybe there are songs that have more information for me!)","sourceKey":"Dialog:context:CityEventH03-10","speaker":"{playerName}"},{"number":11,"text":"Is there a second part to the song you just sang?","sourceKey":"Dialog:context:CityEventH03-11","speaker":"{playerName}"},{"number":12,"text":"You mean you actually enjoyed it? The text of the prophecy book only appeareth every so often... Who knoweth when the next time will be.","sourceKey":"Dialog:context:CityEventH03-12","speaker":null},{"number":13,"text":"Then please stay here! I'll compensate you, just keep singing that song!","sourceKey":"Dialog:context:CityEventH03-13","speaker":"{playerName}"},{"number":14,"text":"Indeed...? ‘Tis quite against my expectations, but since thou wishest it, I shall not refuse~","sourceKey":"Dialog:context:CityEventH03-14","speaker":null},{"number":15,"text":"Most excellent, I shall abide here for a spell. Should you wish to hear another ballad, my lute is at thy command~","sourceKey":"Dialog:context:CityEventH03-15","speaker":null}]},{"id":"CityEventH05","characterId":"hero_5","lines":[{"number":1,"text":"*Ding-dong, ding-dong!*","sourceKey":"Dialog:context:CityEventH05-1","speaker":"Doorbell"},{"number":2,"text":"Who's knocking at the door so early in the morning? Coming, coming...","sourceKey":"Dialog:context:CityEventH05-2","speaker":"{playerName}"},{"number":3,"text":"...","sourceKey":"Dialog:context:CityEventH05-3","speaker":"Big pumpkin"},{"number":4,"text":"A p-pumpkin...?","sourceKey":"Dialog:context:CityEventH05-4","speaker":"{playerName}"},{"number":5,"text":"Why, good morning! What a wonderful day for farming!","sourceKey":"Dialog:context:CityEventH05-5","speaker":"Big Pumpkin"},{"number":6,"text":"Did the pumpkin just speak!?","sourceKey":"Dialog:context:CityEventH05-6","speaker":"{playerName}"},{"number":7,"text":"Sorry to startle you. I'll stand... ","sourceKey":"Dialog:context:CityEventH05-7","speaker":null},{"number":8,"text":"Oh, it's you, Pump. What brings you here?","sourceKey":"Dialog:context:CityEventH05-8","speaker":"{playerName}"},{"number":9,"text":"I caused some trouble for ya in Drakenberg before, I've been wanting to come and thank you in person.","sourceKey":"Dialog:context:CityEventH05-9","speaker":null},{"number":10,"text":"The crops I've been growin' just ripened, and they are especially plump, so I decided to bring a cartload over to ya by way of apology~","sourceKey":"Dialog:context:CityEventH05-10","speaker":null},{"number":11,"text":"Oh, please, there's no need, it was nothing.","sourceKey":"Dialog:context:CityEventH05-11","speaker":"{playerName}"},{"number":12,"text":"Hehe, that's mighty kind of you~ Besides the apology, I also have a humble request...","sourceKey":"Dialog:context:CityEventH05-12","speaker":null},{"number":13,"text":"I saw everythin' you did in Drakenberg, yer even a match for an Archdemon. Who'd have thought!","sourceKey":"Dialog:context:CityEventH05-13","speaker":null},{"number":14,"text":"And you manage such a beautiful village... I saw that there's a farmstead on the outskirts of the village, I was wonderin' if ya might be willing to let me stay there and ply my trade?","sourceKey":"Dialog:context:CityEventH05-14","speaker":null},{"number":15,"text":"You'd like to come to the village? That's fantastic! You're the only one who can grow such delicious vegetables~","sourceKey":"Dialog:context:CityEventH05-15","speaker":"{playerName}"},{"number":16,"text":"Hahaha~ Now yer talkin' sense! It's settled then, come find me anytime if you want some fresh vegetables!","sourceKey":"Dialog:context:CityEventH05-16","speaker":null}]},{"id":"CityEventH51","characterId":"hero_51","lines":[{"number":1,"text":"A group of villagers have gathered in a raucous circle and seem to watching someone.","sourceKey":"Dialog:context:CityEventH51-1","speaker":"empty"},{"number":2,"text":"You push your way to the front of the crowd and peek through to see a dwarven girl showing off a strange spray gun.","sourceKey":"Dialog:context:CityEventH51-2","speaker":"empty"},{"number":3,"text":"This \"multifunctional spray gun” I designed has several special features! For example, turn this knob here and press the switch... See— fire!","sourceKey":"Dialog:context:CityEventH51-3","speaker":"???"},{"number":4,"text":"But how can this be used? It's cheaper and more convenient to just use a flint stone for lighting fires.","sourceKey":"Dialog:context:CityEventH51-4","speaker":"Villager 1"},{"number":5,"text":"Then what about this! Turn the knob backwards, then press the switch... and— wind~! Isn't that cool? You can use it to cool off in the summer~","sourceKey":"Dialog:context:CityEventH51-5","speaker":"???"},{"number":6,"text":"But the wind is weak, and you have to hold it, so tiring... I can get a better breeze, a good view, and a seat in the shade down by the riverbank.","sourceKey":"Dialog:context:CityEventH51-6","speaker":"Villager 2"},{"number":7,"text":"Hmm...","sourceKey":"Dialog:context:CityEventH51-7","speaker":"???"},{"number":8,"text":"(What's going on? The shape of that spray gun looks familiar somehow... Ah! Isn't that...)","sourceKey":"Dialog:context:CityEventH51-8","speaker":"{playerName}"},{"number":9,"text":"I have a suggestion: why not try combining these two functions together? For example, set the spray gun to blow warm wind~!","sourceKey":"Dialog:context:CityEventH51-9","speaker":"{playerName}"},{"number":10,"text":"Oho~! Now that feels great! I can dry my hair after taking a bath with this! That way I won't catch a cold!","sourceKey":"Dialog:context:CityEventH51-10","speaker":"Villager 1"},{"number":11,"text":"Can it be used to dry freshly washed clothes? That would be really useful~!","sourceKey":"Dialog:context:CityEventH51-11","speaker":"Villager 2"},{"number":12,"text":"Oh... oooh~! That does make sense! My name is Quenchy, a craftsman. Your ideas are great. Are you also a researcher~?","sourceKey":"Dialog:context:CityEventH51-12","speaker":"Quenchy"},{"number":13,"text":"No, I'm the Village Elder here, {playerName}.","sourceKey":"Dialog:context:CityEventH51-13","speaker":"{playerName}"},{"number":14,"text":"The Village Elder, eh... so you are the boss~! Do you need any craftsmen around here? I have lots of amazing inventions—","sourceKey":"Dialog:context:CityEventH51-14","speaker":"Quenchy"},{"number":15,"text":"A map that can automatically guide you, a hat that can play music, and gloves that can make you strong after wearing them!","sourceKey":"Dialog:context:CityEventH51-15","speaker":"Quenchy"},{"number":16,"text":"You can try them out as much as you want. If you ever design something new, I can help too~","sourceKey":"Dialog:context:CityEventH51-16","speaker":"Quenchy"},{"number":17,"text":"Oh— and if you have any cool ideas, remember to tell me! I’ll turn your inspiration into reality~!","sourceKey":"Dialog:context:CityEventH51-17","speaker":"Quenchy"}]},{"id":"CityEventH55","characterId":"hero_55","lines":[{"number":1,"text":"Woah… This seems to be the place to cook cuisines with unforgettable flavour.","sourceKey":"Dialog:context:CityEventH55-1","speaker":null},{"number":2,"text":"You're the manager here? Hmph, you're quite young.","sourceKey":"Dialog:context:CityEventH55-2","speaker":null},{"number":3,"text":"I'm a cook and you can call me Moork. I came here following the scent of delicious food and it seems that I've found the right place…","sourceKey":"Dialog:context:CityEventH55-3","speaker":null},{"number":4,"text":"(Huh? The smell of something delicious... Is it coming towards me...?)","sourceKey":"Dialog:context:CityEventH55-4","speaker":"{playerName}"},{"number":5,"text":"No way—! I'm not tasty at all!","sourceKey":"Dialog:context:CityEventH55-5","speaker":"{playerName}"},{"number":6,"text":"What are you talking about? Who wants to eat you...? Wait, are you actually edible?","sourceKey":"Dialog:context:CityEventH55-6","speaker":null},{"number":7,"text":"Of course not! You just said you smelled something delicious, but there’s nothing tasty around here...","sourceKey":"Dialog:context:CityEventH55-7","speaker":"{playerName}"},{"number":8,"text":"Ingredients? Humph, even a third-rate chef can make delicious food with top-quality ingredients, so that stuff is basically meaningless.","sourceKey":"Dialog:context:CityEventH55-8","speaker":null},{"number":9,"text":"For me, the most important thing in cooking delicious food is the “story.\" Only by adding stories can you create unforgettable memories for the diners.","sourceKey":"Dialog:context:CityEventH55-9","speaker":null},{"number":10,"text":"Even with ordinary ingredients, you must be able to create a flavor powerful enough to move people to tears. That's what makes a true chef proud.","sourceKey":"Dialog:context:CityEventH55-10","speaker":null},{"number":11,"text":"There are so many unforgettable memories in this village... Your new injury must also have an exciting story behind it, right?","sourceKey":"Dialog:context:CityEventH55-11","speaker":null},{"number":12,"text":"Injury? Whoa, when did that happen...? I must have fallen and hurt myself while playing around with everyone the other day...","sourceKey":"Dialog:context:CityEventH55-12","speaker":"{playerName}"},{"number":13,"text":"So that story... that probably doesn’t count as exciting, does it?","sourceKey":"Dialog:context:CityEventH55-13","speaker":"{playerName}"},{"number":14,"text":"Hehehe... but isn't that great in itself? The taste of happiness was enough to make you forget the pain— that taste is surely sweeter than any dessert.","sourceKey":"Dialog:context:CityEventH55-14","speaker":null},{"number":15,"text":"This world certainly has its share of suffering, so perhaps the cuisine that best suits this village should be called... “Happiness,” as you wish.","sourceKey":"Dialog:context:CityEventH55-15","speaker":null}]},{"id":"CityEventH58","characterId":"hero_58","lines":[{"number":1,"text":"...... Report to {playerName}, Denisa, as the guild deployment requires.","sourceKey":"Dialog:context:CityEventH58-1","speaker":null},{"number":2,"text":"Please arrange for me to go to a suitable place to work and tell me about the content of the job content as soon as possible. I will officially start work tomorrow.","sourceKey":"Dialog:context:CityEventH58-2","speaker":null},{"number":3,"text":"Eh? May I ask who you are...?","sourceKey":"Dialog:context:CityEventH58-3","speaker":"{playerName}"},{"number":4,"text":"I am a guild envoy dispatched by the Adventurer's Guild, responsible for assisting you with guild-related tasks...","sourceKey":"Dialog:context:CityEventH58-4","speaker":null},{"number":5,"text":"...Ah, it's time.","sourceKey":"Dialog:context:CityEventH58-5","speaker":null},{"number":6,"text":"Ah, that's great. There are quite a few things over here that I need your help with.","sourceKey":"Dialog:context:CityEventH58-6","speaker":"{playerName}"},{"number":7,"text":"Although it may be a bit late now, shall I first familiarize you with the job responsibilities?","sourceKey":"Dialog:context:CityEventH58-7","speaker":"{playerName}"},{"number":8,"text":"...","sourceKey":"Dialog:context:CityEventH58-8","speaker":null},{"number":9,"text":"...Hm? What's wrong?","sourceKey":"Dialog:context:CityEventH58-9","speaker":"{playerName}"},{"number":10,"text":"...It's already time to get off work. If you have anything, please come back tomorrow.","sourceKey":"Dialog:context:CityEventH58-10","speaker":null},{"number":11,"text":"Eh? Is this...really happening?","sourceKey":"Dialog:context:CityEventH58-11","speaker":"{playerName}"},{"number":12,"text":"I am an anti-overtime advocate, but I will complete the tasks you assign on time. Please give me your guidance in the future.","sourceKey":"Dialog:context:CityEventH58-12","speaker":null}]},{"id":"CityEventH59","characterId":"hero_59","lines":[{"number":1,"text":"... Ah, found it.","sourceKey":"Dialog:context:CityEventH59-1","speaker":null},{"number":2,"text":"Huh? Are you here to see me?","sourceKey":"Dialog:context:CityEventH59-2","speaker":"{playerName}"},{"number":3,"text":"(Nods)","sourceKey":"Dialog:context:CityEventH59-3","speaker":null},{"number":4,"text":"... I'm sorry, have we met before?","sourceKey":"Dialog:context:CityEventH59-4","speaker":"{playerName}"},{"number":5,"text":"... You saved my life.","sourceKey":"Dialog:context:CityEventH59-5","speaker":null},{"number":6,"text":"The girl instantly transforms into a small spider.","sourceKey":"Dialog:context:CityEventH59-6","speaker":"empty"},{"number":7,"text":"A spider!? I feel like I've seen you somewhere before... Oh—now I remember! I met you in the Evil Forest!","sourceKey":"Dialog:context:CityEventH59-7","speaker":"{playerName}"},{"number":8,"text":"To think you came to see me... and even transformed into a cute young woman to do so!","sourceKey":"Dialog:context:CityEventH59-8","speaker":"{playerName}"},{"number":9,"text":"My mother said I must repay the debt.","sourceKey":"Dialog:context:CityEventH59-9","speaker":null},{"number":10,"text":"Do you like this form? I hope we can get on in the future too.","sourceKey":"Dialog:context:CityEventH59-10","speaker":null}]},{"id":"CityEventH60","characterId":"hero_60","lines":[{"number":1,"text":"{playerName}, do you remember me?","sourceKey":"Dialog:context:CityEventH60-1","speaker":null},{"number":2,"text":"We had a chance encounter in Drakenberg.","sourceKey":"Dialog:context:CityEventH60-2","speaker":null},{"number":3,"text":"I remember! You're that weirdo who's been following the miko around.","sourceKey":"Dialog:context:CityEventH60-3","speaker":"{playerName}"},{"number":4,"text":"Hehe, did you also notice that my relationship with that miko is unusual? I'm really sorry.","sourceKey":"Dialog:context:CityEventH60-4","speaker":null},{"number":5,"text":"(Where are you feeling embarrassed?)","sourceKey":"Dialog:context:CityEventH60-5","speaker":"{playerName}"},{"number":6,"text":"The miko really likes your village and is considering moving here.","sourceKey":"Dialog:context:CityEventH60-6","speaker":null},{"number":7,"text":"Wherever there is a miko, there I am.","sourceKey":"Dialog:context:CityEventH60-7","speaker":null},{"number":8,"text":"Do you mind if I stay over? I won't freeload in your village.","sourceKey":"Dialog:context:CityEventH60-8","speaker":null},{"number":9,"text":"Please arrange some work for me, especially the ones related to miko. Thank you!","sourceKey":"Dialog:context:CityEventH60-9","speaker":null}]},{"id":"CityEventH61","characterId":"hero_61","lines":[{"number":1,"text":"(Hey... isn't that Cimitir? Why does she look so upset...? I should ask her.)","sourceKey":"Dialog:context:CityEventH61-1","speaker":"{playerName}"},{"number":2,"text":"Um, Cimitir, it's already so late. What are you doing here?","sourceKey":"Dialog:context:CityEventH61-2","speaker":"{playerName}"},{"number":3,"text":"I'm perfecting the design for the inn renovations. I've completed two plans but they're still not quite up to scratch...","sourceKey":"Dialog:context:CityEventH61-3","speaker":"Cimitir"},{"number":4,"text":"(Let me see... Both of these plans look perfect to me... It wouldn’t be Cimitir if she wasn’t striving for absolute perfection.)","sourceKey":"Dialog:context:CityEventH61-4","speaker":"{playerName}"},{"number":5,"text":"A pointed roof...? That doesn't look like an inn. But then if we use a flat roof, it would be too plain and have no character... Maybe a curved roof?","sourceKey":"Dialog:context:CityEventH61-5","speaker":"Cimitir"},{"number":6,"text":"(Just watching from here, I can feel the pressure she's putting on herself... This is no good. I’ve got to help her relax.)","sourceKey":"Dialog:context:CityEventH61-6","speaker":"{playerName}"},{"number":7,"text":"Would you like to hear my suggestions~? When you're stuck, sometimes a non-professional opinion might just point out a way, what'd you say~?","sourceKey":"Dialog:context:CityEventH61-7","speaker":"{playerName}"},{"number":8,"text":"...That makes some sense, I suppose. Please tell me your suggestions.","sourceKey":"Dialog:context:CityEventH61-8","speaker":"Cimitir"},{"number":9,"text":"It seems like you're struggling with the shape of the roof— how about incorporating the inn's signature dishes into the design, like a Kitty Sandwich roof, or a hamburger roof~?","sourceKey":"Dialog:context:CityEventH61-9","speaker":"{playerName}"},{"number":10,"text":"Cimitir's expression turns even more serious.","sourceKey":"Dialog:context:CityEventH61-10","speaker":"empty"},{"number":11,"text":"(Uh oh, this is really awkward... I hope she doesn't think I'm making light of her work—)","sourceKey":"Dialog:context:CityEventH61-11","speaker":"{playerName}"},{"number":12,"text":"Ahahaha, just kidding. Actually... Both of your plans are great already. Maybe you should relax a little bit...","sourceKey":"Dialog:context:CityEventH61-12","speaker":"{playerName}"},{"number":13,"text":"I see.","sourceKey":"Dialog:context:CityEventH61-13","speaker":"Cimitir"},{"number":14,"text":"So I mean... you really don't have to… eh?","sourceKey":"Dialog:context:CityEventH61-14","speaker":"{playerName}"},{"number":15,"text":"Your suggestion is quite valuable. It takes both practicality and loveliness into account. It is sure to attract more attention and customers.","sourceKey":"Dialog:context:CityEventH61-15","speaker":"Cimitir"},{"number":16,"text":"I’ll finalize the plans in a day or two according to them. By the way, is there any more buildings need renovation? Leave them to me, I've already come up with several good ideas.","sourceKey":"Dialog:context:CityEventH61-16","speaker":"Cimitir"}]},{"id":"CityEventH62","characterId":"hero_62","lines":[{"number":1,"text":"Excuse me, {playerName}. I am Grayce. From now on, I'll be your exclusive servant.","sourceKey":"Dialog:context:CityEventH62-1","speaker":null},{"number":2,"text":"Grandpa? I feel like I've seen you somewhere before... but as a servant? That's not quite right...","sourceKey":"Dialog:context:CityEventH62-2","speaker":"{playerName}"},{"number":3,"text":"Haha, you've misunderstood. I'm the head waiter of the Banquet Hall in Drakenberg, I’m responsible for arranging the banquet you're hosting.","sourceKey":"Dialog:context:CityEventH62-3","speaker":null},{"number":4,"text":"Thanks to you, guests have been coming in an endless stream to the Banquet Hall. To thank you for your business, we are now pleased to offer you VIP treatment.","sourceKey":"Dialog:context:CityEventH62-4","speaker":null},{"number":5,"text":"VIP treatment?","sourceKey":"Dialog:context:CityEventH62-5","speaker":"{playerName}"},{"number":6,"text":"That’s right. From now on, I'll be your personal attendant responsible for taking care of your affairs.","sourceKey":"Dialog:context:CityEventH62-6","speaker":null},{"number":7,"text":"Oh my, that's too really too much...","sourceKey":"Dialog:context:CityEventH62-7","speaker":"{playerName}"},{"number":8,"text":"Haha, there’s no need to be shy. You're an important guest of ours, so satisfying your needs is my mission as a servant.","sourceKey":"Dialog:context:CityEventH62-8","speaker":null},{"number":9,"text":"If you have no objections, beginning from the banquet tonight, I will provide you with the most comfortable service we can provide.","sourceKey":"Dialog:context:CityEventH62-9","speaker":null}]},{"id":"CityEventH63","characterId":"hero_63","lines":[{"number":1,"text":"Come back and explore this area another time.","sourceKey":"Dialog:context:CityEventH63-1","speaker":null}]},{"id":"CityEventH65","characterId":"hero_65","lines":[{"number":1,"text":"Hello! I'm Brotein, a fitness coach. Someone invited me here to be a personal trainer.","sourceKey":"Dialog:context:CityEventH65-1","speaker":null},{"number":2,"text":"Did you invite me?","sourceKey":"Dialog:context:CityEventH65-2","speaker":null},{"number":3,"text":"Ah? No, it's not like that.","sourceKey":"Dialog:context:CityEventH65-3","speaker":"{playerName}"},{"number":4,"text":"Brotein looked at the invitation letter.","sourceKey":"Dialog:context:CityEventH65-4","speaker":"empty"},{"number":5,"text":"Hmm, it's really not you, but a guard.","sourceKey":"Dialog:context:CityEventH65-5","speaker":null},{"number":6,"text":"I think you, who are thin and weak, need my fitness guidance more than that guard!","sourceKey":"Dialog:context:CityEventH65-6","speaker":null},{"number":7,"text":"Um...thank you, but I don't have that plan.","sourceKey":"Dialog:context:CityEventH65-7","speaker":"{playerName}"},{"number":8,"text":"Hahaha! People who don't have a habit of exercising always say that.","sourceKey":"Dialog:context:CityEventH65-8","speaker":null},{"number":9,"text":"But it's okay! Once you start working out, you'll fall in love with it.","sourceKey":"Dialog:context:CityEventH65-9","speaker":null},{"number":10,"text":"Whenever you have an idea, come find me! I'll tailor a beginner's fitness plan for you!","sourceKey":"Dialog:context:CityEventH65-10","speaker":null}]},{"id":"CityEventW12","characterId":"wife_12","lines":[{"number":1,"text":"(This girl selling food at the stall. Her cooking smells so good...) Excuse me, can I have a serve of over rice, please?","sourceKey":"Dialog:context:CityEventW12-1","speaker":"{playerName}"},{"number":2,"text":"Sure... I hope it suits your taste...","sourceKey":"Dialog:context:CityEventW12-2","speaker":"???"},{"number":3,"text":"Hm? Mm... this taste? It's so delicious! Miss, your cooking skill is amazing!","sourceKey":"Dialog:context:CityEventW12-3","speaker":"{playerName}"},{"number":4,"text":"Haha... th—thank you...","sourceKey":"Dialog:context:CityEventW12-4","speaker":"???"},{"number":5,"text":"Huh? Did I say something wrong?","sourceKey":"Dialog:context:CityEventW12-5","speaker":"{playerName}"},{"number":6,"text":"No, it's not your fault. It's my own problem.","sourceKey":"Dialog:context:CityEventW12-6","speaker":"???"},{"number":7,"text":"My name is Rachel, and I am a chef... I don't even know whether I can be called a chef or not…","sourceKey":"Dialog:context:CityEventW12-7","speaker":null},{"number":8,"text":"I just lost my job at the Drakenberg restaurant, ahaha...","sourceKey":"Dialog:context:CityEventW12-8","speaker":null},{"number":9,"text":"It's not the manager's fault. After all, the other chefs know how to use rare ingredients to make fancy dishes...","sourceKey":"Dialog:context:CityEventW12-9","speaker":null},{"number":10,"text":"All I can make are some home cooking, far from being high-end cuisine... Compared to them, I'm like a wild chicken in a phoenix nest...","sourceKey":"Dialog:context:CityEventW12-10","speaker":null},{"number":11,"text":"Well~ I don't think so. I think Rachel is a great chef.","sourceKey":"Dialog:context:CityEventW12-11","speaker":"{playerName}"},{"number":12,"text":"Ahaha... you're very kind, willing to comfort someone you just met...","sourceKey":"Dialog:context:CityEventW12-12","speaker":null},{"number":13,"text":"It's not comforting. I'm serious. Being able to make home cooking so delicious... Could you have been blessed by the Gourmet God?","sourceKey":"Dialog:context:CityEventW12-13","speaker":"{playerName}"},{"number":14,"text":"There's no “Gourmet God”... and I've never been blessed before…","sourceKey":"Dialog:context:CityEventW12-14","speaker":null},{"number":15,"text":"So it's all self-taught? That's even more impressive~","sourceKey":"Dialog:context:CityEventW12-15","speaker":"{playerName}"},{"number":16,"text":"You can turn ordinary ingredients into extraordinarily delicious dishes, just by using your own skills~","sourceKey":"Dialog:context:CityEventW12-16","speaker":"{playerName}"},{"number":17,"text":"Oh man, I wish I could eat Rachel's cooking every day from now on~","sourceKey":"Dialog:context:CityEventW12-17","speaker":"{playerName}"},{"number":18,"text":"... Are-are you being serious right now?","sourceKey":"Dialog:context:CityEventW12-18","speaker":null},{"number":19,"text":"Of course.","sourceKey":"Dialog:context:CityEventW12-19","speaker":"{playerName}"},{"number":20,"text":"…I'll cook them for you.","sourceKey":"Dialog:context:CityEventW12-20","speaker":null},{"number":21,"text":"Since you mean it, I'll do the home cooking for you every day from now on!","sourceKey":"Dialog:context:CityEventW12-21","speaker":null}]},{"id":"CityEventW19","characterId":"wife_19","lines":[{"number":1,"text":"You're finally back, I waited for ages~","sourceKey":"Dialog:context:CityEventW19-1","speaker":"Monster with Powerful Aura"},{"number":2,"text":"Monsters!? Why are there monsters here...?","sourceKey":"Dialog:context:CityEventW19-2","speaker":"{playerName}"},{"number":3,"text":"You meanie~ You forgot about me in such a short time? You're so naughty~ And after you left such a striking figure in the forest Dungeon...","sourceKey":"Dialog:context:CityEventW19-3","speaker":"Monster with Powerful Aura"},{"number":4,"text":"Forest Dungeon? Could it be monsters from the Drakenberg Challenge? But I don't remember meeting you...","sourceKey":"Dialog:context:CityEventW19-4","speaker":"{playerName}"},{"number":5,"text":"Of course not, I am Otherin, the great sealed monster. I could only admire your bravery in secret~","sourceKey":"Dialog:context:CityEventW19-5","speaker":"Monster with Powerful Aura"},{"number":6,"text":"Hehe, as the hero I have my eyes on, don't even think about escaping~ I will come to play with you often from now on~","sourceKey":"Dialog:context:CityEventW19-6","speaker":null},{"number":7,"text":"Huh? You'll be coming often?","sourceKey":"Dialog:context:CityEventW19-7","speaker":"{playerName}"},{"number":8,"text":"It's all because you have attracted me~ It's your own fault, so be prepared to fall under my control for the rest of your life~","sourceKey":"Dialog:context:CityEventW19-8","speaker":null},{"number":9,"text":"Well then... why don't you come live here?","sourceKey":"Dialog:context:CityEventW19-9","speaker":"{playerName}"},{"number":10,"text":"... Huh?","sourceKey":"Dialog:context:CityEventW19-10","speaker":null},{"number":11,"text":"It's a hassle going back and forth like this all the time, it's much better for everyone to live together~","sourceKey":"Dialog:context:CityEventW19-11","speaker":"{playerName}"},{"number":12,"text":"Moreover, the Drakenberg Challenge's environment is harsh, isn't it? Stay in my house, and you'll be more comfortable. Will you come?","sourceKey":"Dialog:context:CityEventW19-12","speaker":"{playerName}"},{"number":13,"text":"...... Well this is most unexpected. Thank you for the invitation, I won't take one step from your side~","sourceKey":"Dialog:context:CityEventW19-13","speaker":null}]},{"id":"CityEventW3","characterId":"wife_3","lines":[{"number":1,"text":"May I ask if {playerName} is here?","sourceKey":"Dialog:context:CityEventW3-1","speaker":null},{"number":2,"text":"Hmm, are you looking for me? Hi there, what can I do for you?","sourceKey":"Dialog:context:CityEventW3-2","speaker":"{playerName}"},{"number":3,"text":"Liar! There's no way someone so harmless-looking could be the big shot of the Trading Post! He must be a crafty, jaded old merchant!","sourceKey":"Dialog:context:CityEventW3-3","speaker":null},{"number":4,"text":"Eh? What are you talking about?","sourceKey":"Dialog:context:CityEventW3-4","speaker":"{playerName}"},{"number":5,"text":"He has power beyond measure and preys on innocent girls, making their lives a living hell...","sourceKey":"Dialog:context:CityEventW3-5","speaker":null},{"number":6,"text":"As a knight, I am here to fight for justice, but I too ended up becoming part of his \"collection” and got humiliated... Yaaaah—!","sourceKey":"Dialog:context:CityEventW3-6","speaker":null},{"number":7,"text":"What's going on? What are you talking about? Please calm down!","sourceKey":"Dialog:context:CityEventW3-7","speaker":"{playerName}"},{"number":8,"text":"Yaaah......! I'm sorry, I lost my composure just now... Anyway, release all the girls you have imprisoned—at once!","sourceKey":"Dialog:context:CityEventW3-8","speaker":null},{"number":9,"text":"I don't know what led to this misunderstanding, but I'm not that kind of person...","sourceKey":"Dialog:context:CityEventW3-9","speaker":"{playerName}"},{"number":10,"text":"While it's true that I've taken some people in, they're all like family to me. How could I possibly mistreat them?","sourceKey":"Dialog:context:CityEventW3-10","speaker":"{playerName}"},{"number":11,"text":"“Family”...? Humph! I won’t believe such an explanation! There’s no way there’s someone this good!","sourceKey":"Dialog:context:CityEventW3-11","speaker":null},{"number":12,"text":"It seems I must personally experience this hardship in order to expose your lies!","sourceKey":"Dialog:context:CityEventW3-12","speaker":null},{"number":13,"text":"Wait, now what's happening...?","sourceKey":"Dialog:context:CityEventW3-13","speaker":"{playerName}"},{"number":14,"text":"From now on, I will watch over you closely! You won't be able to deceive me!","sourceKey":"Dialog:context:CityEventW3-14","speaker":null}]},{"id":"CityEventW4","characterId":"wife_4","lines":[{"number":1,"text":"Our village has been developing so well~ We need to work hard not to fall behind... Ouch!","sourceKey":"Dialog:context:CityEventW4-1","speaker":"{playerName}"},{"number":2,"text":"W-what was that...? Hmm? There wasn't a tree stump here before... It's in the way, we'd better move it—","sourceKey":"Dialog:context:CityEventW4-2","speaker":"{playerName}"},{"number":3,"text":"——! Don't... don't touch that place—!","sourceKey":"Dialog:context:CityEventW4-3","speaker":null},{"number":4,"text":"Augh! The stump... talked!? No, it turned into a beautiful young woman!","sourceKey":"Dialog:context:CityEventW4-4","speaker":"{playerName}"},{"number":5,"text":"Umm, actually I am a ninja... This is my true form.","sourceKey":"Dialog:context:CityEventW4-5","speaker":null},{"number":6,"text":"A ninja? The kind that uses super cool ninja techniques!?","sourceKey":"Dialog:context:CityEventW4-6","speaker":"{playerName}"},{"number":7,"text":"No, my training is still far from being complete. I just wanted to observe you from afar...","sourceKey":"Dialog:context:CityEventW4-7","speaker":null},{"number":8,"text":"My self-control is still too poor, I got too close to you by accident and had to use my transformation technique to hide...","sourceKey":"Dialog:context:CityEventW4-8","speaker":null},{"number":9,"text":"I'm sorry for causing you trouble...","sourceKey":"Dialog:context:CityEventW4-9","speaker":null},{"number":10,"text":"No, it's no trouble at all. You didn't do anything wrong... But why did you watch me from a distance?","sourceKey":"Dialog:context:CityEventW4-10","speaker":"{playerName}"},{"number":11,"text":"Um, well... It's embarrassing, but... I really admire you for being able to help others with your power...","sourceKey":"Dialog:context:CityEventW4-11","speaker":null},{"number":12,"text":"I'm sorry, I'll leave now...","sourceKey":"Dialog:context:CityEventW4-12","speaker":null},{"number":13,"text":"No, what I meant was: if you want to watch, you could just come closer~","sourceKey":"Dialog:context:CityEventW4-13","speaker":"{playerName}"},{"number":14,"text":"If we lived like \"family\", we can see each other every day. What do you think, would you like that?","sourceKey":"Dialog:context:CityEventW4-14","speaker":"{playerName}"},{"number":15,"text":"Really, is that okay? That's a big gift for a ninja to receive...","sourceKey":"Dialog:context:CityEventW4-15","speaker":null},{"number":16,"text":"Well then, thank you for accepting me... I am Nene, a ninja of the Togakure clan, I pledge to obey you from now on.","sourceKey":"Dialog:context:CityEventW4-16","speaker":null}]},{"id":"CityEventW51","characterId":"wife_51","lines":[{"number":1,"text":"Nurse Baity, here to report~ The health check {playerName} scheduled can begin soon, please remember to eat light during this period~","sourceKey":"Dialog:context:CityEventW51-1","speaker":null},{"number":2,"text":"A nurse? A health check? Wait, when did I schedule this...","sourceKey":"Dialog:context:CityEventW51-2","speaker":"{playerName}"},{"number":3,"text":"You didn't say a word; as a professional nurse, I have heard the voice of the blood in your body~","sourceKey":"Dialog:context:CityEventW51-3","speaker":null},{"number":4,"text":"Wha-what does that mean!?","sourceKey":"Dialog:context:CityEventW51-4","speaker":"{playerName}"},{"number":5,"text":"\"Stays up late every night until early morning.” \"Dislikes eating vegetables.” \"Rarely exercises...\"","sourceKey":"Dialog:context:CityEventW51-5","speaker":null},{"number":6,"text":"Whoa! How did you know all that?","sourceKey":"Dialog:context:CityEventW51-6","speaker":"{playerName}"},{"number":7,"text":"The blood in your body told me~ This can't go on, the blood will be unhappy...","sourceKey":"Dialog:context:CityEventW51-7","speaker":null},{"number":8,"text":"Let me take care of your health~ I guarantee your blood will become even more delicious~","sourceKey":"Dialog:context:CityEventW51-8","speaker":null}]},{"id":"CityEventW62","characterId":"wife_62","lines":[{"number":1,"text":"Hello, {playerName}, I'm Nousa, a teacher. I've heard of your name for a long time and came to visit you today.","sourceKey":"Dialog:context:CityEventW62-1","speaker":null},{"number":2,"text":"I seek the protection of a wise lord to develop my educational career. Only in a peaceful and tranquil place can children grow up healthy and strong.","sourceKey":"Dialog:context:CityEventW62-2","speaker":null},{"number":3,"text":"After this period of contact, from the most rational perspective, I believe that you are the ideal choice.","sourceKey":"Dialog:context:CityEventW62-3","speaker":null},{"number":4,"text":"I wonder if you are willing to accept me?","sourceKey":"Dialog:context:CityEventW62-4","speaker":null},{"number":5,"text":"Hey? Of course, you're welcome. But have we met before?","sourceKey":"Dialog:context:CityEventW62-5","speaker":"{playerName}"},{"number":6,"text":"This is our first meeting, right? Why did you choose me?","sourceKey":"Dialog:context:CityEventW62-6","speaker":"{playerName}"},{"number":7,"text":"It may be a first meeting for you, but we have already met many times before.","sourceKey":"Dialog:context:CityEventW62-7","speaker":null},{"number":8,"text":"As a teacher, I often attend various banquets and always see your figure.","sourceKey":"Dialog:context:CityEventW62-8","speaker":null},{"number":9,"text":"People are most likely to show their true nature when they are in a relaxed state. Even the charming and elegant elites can reveal their wolfish nature after getting drunk.","sourceKey":"Dialog:context:CityEventW62-9","speaker":null},{"number":10,"text":"But only you have always shown courtesy, kindness, elegance, and most importantly, goodwill no matter when.","sourceKey":"Dialog:context:CityEventW62-10","speaker":null},{"number":11,"text":"After extensive observation, I have determined that you are a trustworthy person. You will be an excellent role model for the pupils.","sourceKey":"Dialog:context:CityEventW62-11","speaker":null},{"number":12,"text":"In the long journey of life, the chance to join someone as outstanding as you is a precious gift bestowed by probability.","sourceKey":"Dialog:context:CityEventW62-12","speaker":null},{"number":13,"text":"In order to thank you for taking me in, I will also provide help of equal value.","sourceKey":"Dialog:context:CityEventW62-13","speaker":null}]},{"id":"CityEventW63","characterId":"wife_63","lines":[{"number":1,"text":"Greetings, I am a sommelier named Pinor. I have heard so much about you, I shall take only a minute of your time today.","sourceKey":"Dialog:context:CityEventW63-1","speaker":null},{"number":2,"text":"I had the pleasure of attending a banquet you were at before, and I'd like to ask how you would evaluate the taste of the wine we had during the feast.","sourceKey":"Dialog:context:CityEventW63-2","speaker":null},{"number":3,"text":"Eh? Wine? I don't remember much, but it was good, wasn't it? We certainly had a great time at the party.","sourceKey":"Dialog:context:CityEventW63-3","speaker":"{playerName}"},{"number":4,"text":"I've never studied wine or alcohol, I've always had more of a \"let's just enjoy it\" kind of attitude... If you know what I mean.","sourceKey":"Dialog:context:CityEventW63-4","speaker":"{playerName}"},{"number":5,"text":"The view you inadvertently expressed is in fact something that many celebrities will never understand. Like me, for instance...","sourceKey":"Dialog:context:CityEventW63-5","speaker":null},{"number":6,"text":"Watching you drinking away happily at that table of nobility, I sat alone in my chair and simply couldn't find joy in my cup...","sourceKey":"Dialog:context:CityEventW63-6","speaker":null},{"number":7,"text":"I think I know how to clear up your confusion; wine is meant to be shared with others~","sourceKey":"Dialog:context:CityEventW63-7","speaker":"{playerName}"},{"number":8,"text":"It must be someone you're close with, then the wine will taste as wonderful as the company~","sourceKey":"Dialog:context:CityEventW63-8","speaker":"{playerName}"},{"number":9,"text":"That is an extremely novel idea. The only people who ever invite me are snobbish wine merchants who only care about fame and fortune...","sourceKey":"Dialog:context:CityEventW63-9","speaker":null},{"number":10,"text":"Though I suppose I count as a celebrity of sorts, I'm embarrassed to admit that there is no one with whom I can share a casual drink.","sourceKey":"Dialog:context:CityEventW63-10","speaker":null},{"number":11,"text":"Well, now you do~ If you're willing, I'd love to become someone you'd want to share a quiet drink with!","sourceKey":"Dialog:context:CityEventW63-11","speaker":"{playerName}"},{"number":12,"text":"If you ever want to have a glass and chat, just come find me. I guarantee the wine will taste better~","sourceKey":"Dialog:context:CityEventW63-12","speaker":"{playerName}"},{"number":13,"text":"My... So very unlike those superficial crowds, your invitation feels totally sincere and warmhearted...","sourceKey":"Dialog:context:CityEventW63-13","speaker":null},{"number":14,"text":"If you're interested, let's have a drink together!","sourceKey":"Dialog:context:CityEventW63-14","speaker":"{playerName}"},{"number":15,"text":"I shall be happy to oblige...! Hey, this glass of wine truly is refreshing to both the heart and soul~","sourceKey":"Dialog:context:CityEventW63-15","speaker":null}]},{"id":"CityEventW64","characterId":"wife_64","lines":[{"number":1,"text":"Hello, {playerName}, I'm Nousa, a teacher. I've heard of your name for a long time and came to visit you today.","sourceKey":"Dialog:context:CityEventW64-1","speaker":null},{"number":2,"text":"I seek the protection of a wise lord to develop my educational career. Only in a peaceful and tranquil place can children grow up healthy and strong.","sourceKey":"Dialog:context:CityEventW64-2","speaker":null},{"number":3,"text":"After this period of contact, from the most rational perspective, I believe that you are the ideal choice.","sourceKey":"Dialog:context:CityEventW64-3","speaker":null},{"number":4,"text":"I wonder if you are willing to accept me?","sourceKey":"Dialog:context:CityEventW64-4","speaker":null},{"number":5,"text":"Hey? Of course, you're welcome. But have we met before?","sourceKey":"Dialog:context:CityEventW64-5","speaker":"{playerName}"},{"number":6,"text":"This is our first meeting, right? Why did you choose me?","sourceKey":"Dialog:context:CityEventW64-6","speaker":"{playerName}"},{"number":7,"text":"It may be a first meeting for you, but we have already met many times before.","sourceKey":"Dialog:context:CityEventW64-7","speaker":null},{"number":8,"text":"As a teacher, I often attend various banquets and always see your figure.","sourceKey":"Dialog:context:CityEventW64-8","speaker":null},{"number":9,"text":"People are most likely to show their true nature when they are in a relaxed state. Even the charming and elegant elites can reveal their wolfish nature after getting drunk.","sourceKey":"Dialog:context:CityEventW64-9","speaker":null},{"number":10,"text":"But only you have always shown courtesy, kindness, elegance, and most importantly, goodwill no matter when.","sourceKey":"Dialog:context:CityEventW64-10","speaker":null},{"number":11,"text":"After extensive observation, I have determined that you are a trustworthy person. You will be an excellent role model for the pupils.","sourceKey":"Dialog:context:CityEventW64-11","speaker":null},{"number":12,"text":"In the long journey of life, the chance to join someone as outstanding as you is a precious gift bestowed by probability.","sourceKey":"Dialog:context:CityEventW64-12","speaker":null},{"number":13,"text":"In order to thank you for taking me in, I will also provide help of equal value.","sourceKey":"Dialog:context:CityEventW64-13","speaker":null}]}],"excluded":[],"sourceHash":"49f8cd9c5468ea1c29245a4d4f4cc94b00fa8c512efd9912fcf8c7487c8af3f6"};
